    css: "/* From Uiverse.io by Lmickk2 - Tags: switch, light, toggle */\n.switch {\n  font-size: 17px;\n  position: relative;\n  display: inline-block;\n  width: 4.5em;\n  height: 2em;\n}\n\n.switch input {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n\n.slider {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  box-shadow: inset 1px 2px 5px 1px rgba(0, 0, 0, 0.329);\n  transition: .4s;\n  border-radius: 30px;\n}\n\n.slider:before {\n  position: absolute;\n  content: \"\";\n  height: 1.4em;\n  width: 1.4em;\n  border-radius: 20px;\n  left: 0.3em;\n  bottom: 0.3em;\n  background-color: rgb(255, 255, 255);\n  transition: .4s;\n}\n\n.switch input:checked + .slider {\n  background-color: #59c76b;\n}\n\n.switch input:focus + .slider {\n  box-shadow: inset 3px 2px 4px rgba(22, 22, 22, 0.253);\n}\n\n.switch input:checked + .slider:before {\n  transform: translateX(2.5em);\n}",
