    css: "/* From Uiverse.io by YaroslavFilipenko - Tags: slider, input, toggle switch */\n.switch {\n  position: relative;\n  display: inline-block;\n  width: 60px;\n  height: 20px;\n}\n\n.switch input {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n\n.slider {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #b1b9c3;\n  -webkit-transition: 0.4s;\n  transition: 0.4s;\n}\n\n.slider:before {\n  position: absolute;\n  content: '';\n  height: 30px;\n  width: 30px;\n  bottom: -5px;\n  background: #18333E;\n  -webkit-transition: 0.4s;\n  transition: 0.4s;\n}\n\n.slider.round {\n  border-radius: 34px;\n}\n\n.slider.round:before {\n  border-radius: 50%;\n}\n\ninput:checked+.slider {\n  background-color: #b1b9c3;\n}\n\ninput:checked+.slider:before {\n  -webkit-transform: translateX(35px);\n  -ms-transform: translateX(35px);\n  transform: translateX(35px);\n  background: #F2F8FD;\n}",
