    css: "/* From Uiverse.io by mobinkakei - Tags: neumorphism, switch, on, off, bluetooth */\n.switch-holder {\n  display: flex;\n  padding: 10px 20px;\n  border-radius: 10px;\n  box-shadow: -8px -8px 15px rgba(255, 255, 255, .7),\n        10px 10px 10px rgba(0, 0, 0, .2),\n        inset 8px 8px 15px rgba(255, 255, 255, .7),\n        inset 10px 10px 10px rgba(0, 0, 0, .2);\n  justify-content: space-between;\n  align-items: center;\n}\n\n.switch-label {\n  padding: 0 20px 0 10px\n}\n\n.switch-label i {\n  margin-right: 5px;\n}\n\n.switch-toggle {\n  height: 40px;\n}\n\n.switch-toggle input[type=\"checkbox\"] {\n  position: absolute;\n  opacity: 0;\n  z-index: -2;\n}\n\n.switch-toggle input[type=\"checkbox\"]+label {\n  position: relative;\n  display: inline-block;\n  width: 100px;\n  height: 40px;\n  border-radius: 20px;\n  margin: 0;\n  cursor: pointer;\n  box-shadow: inset -8px -8px 15px rgba(255, 255, 255, .6),\n        inset 10px 10px 10px rgba(0, 0, 0, .25);\n}\n\n.switch-toggle input[type=\"checkbox\"]+label::before {\n  position: absolute;\n  content: 'OFF';\n  font-size: 13px;\n  text-align: center;\n  line-height: 25px;\n  top: 8px;\n  left: 8px;\n  width: 45px;\n  height: 25px;\n  border-radius: 20px;\n  background-color: #eeeeee;\n  box-shadow: -3px -3px 5px rgba(255, 255, 255, .5),\n        3px 3px 5px rgba(0, 0, 0, .25);\n  transition: .3s ease-in-out;\n}\n\n.switch-toggle input[type=\"checkbox\"]:checked+label::before {\n  left: 50%;\n  content: 'ON';\n  color: #fff;\n  background-color: #00b33c;\n  box-shadow: -3px -3px 5px rgba(255, 255, 255, .5),\n        3px 3px 5px #00b33c;\n}",
