    css: "/* From Uiverse.io by mrhyddenn - Tags: switch */\n/* The switch - the box around the slider */\n.switch {\n font-size: 17px;\n position: relative;\n display: inline-block;\n width: 62px;\n height: 35px;\n}\n\n/* Hide default HTML checkbox */\n.switch input {\n opacity: 1;\n width: 0;\n height: 0;\n}\n\n/* The slider */\n.slider {\n position: absolute;\n cursor: pointer;\n top: 0;\n left: 0;\n right: 0;\n bottom: 0px;\n background: #fff;\n transition: .4s;\n border-radius: 30px;\n border: 1px solid #ccc;\n}\n\n.slider:before {\n position: absolute;\n content: \"\";\n height: 1.9em;\n width: 1.9em;\n border-radius: 16px;\n left: 1.2px;\n top: 0;\n bottom: 0;\n background-color: white;\n box-shadow: 0 2px 5px #999999;\n transition: .4s;\n}\n\ninput:checked + .slider {\n background-color: #5fdd54;\n border: 1px solid transparent;\n}\n\ninput:checked + .slider:before {\n transform: translateX(1.5em);\n}",
