    html: "<input id=\"toggle_checkbox\" type=\"checkbox\">\n<label for=\"toggle_checkbox\"></label>",
    css: "/* From Uiverse.io by JkHuger - Tags: switch */\n#toggle_checkbox {\n  display: none;\n}\n\nlabel {\n  position: absolute;\n  top: 50%;\n  right: 0px;\n  left: 0;\n  display: block;\n  width: 70px;\n  height: 35px;\n  margin: 0 auto;\n  transform: translateY(-50%);\n  cursor: pointer;\n}\n\nlabel:before {\n  top: 4px;\n  left: 4px;\n  width: 27px;\n  height: 27px;\n  border: 2px solid red;\n}\n\nlabel:after {\n  top: 0;\n  right: 0;\n  width: 70px;\n  height: 35px;\n  border: 2px solid #143240;\n}\n\nlabel:before,\nlabel:after {\n  content: \"\";\n  position: absolute;\n  border-radius: 50px;\n  box-sizing: border-box;\n  transition: 0.5s ease top, 0.5s ease left, 0.5s ease right, 0.5s ease width,\n    0.5s ease height, 0.5s ease border-color;\n}\n\n#toggle_checkbox:checked + label:before {\n  top: 0;\n  left: 0;\n  width: 70px;\n  height: 35px;\n  border-color: #143240;\n  border: 2px solid #143240\n}\n\n#toggle_checkbox:checked + label:after {\n  top: 4px;\n  right: 4px;\n  width: 27px;\n  height: 27px;\n  border-color: red;\n  border: 2px solid red;\n}",
