    html: "<label class=\"switch\">\n  <input type=\"checkbox\">\n  <span class=\"slider\">\n    <div class=\"circle\">\n      <div class=\"divider\"></div>\n    </div>\n  </span>\n</label>",
    css: "/* From Uiverse.io by nanda248 - Tags: switch, light&dark, AM/PM */\n/* The switch - the box around the slider */\n.switch {\n  font-size: 17px;\n  position: relative;\n  display: inline-block;\n  width: 4em;\n  height: 2em;\n}\n\n/* Hide default HTML checkbox */\n.switch input {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n\n/* The slider */\n.slider {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #585F60;\n  transition: .5s;\n  border-radius: 1em;\n  z-index: 1;\n}\n\n.slider .circle {\n  position: absolute;\n  content: \"\";\n  height: 1.4em;\n  width: 1.4em;\n  border-radius: 50%;\n  left: 0.3em;\n  bottom: 0.3em;\n  background-color: #F1EEF5;\n  transition: .5s;\n  z-index: 5;\n}\n\n.divider {\n  position: absolute;\n  left: 0.65em;\n  width: 0.8em;\n  height: 1.4em;\n  background-color: #eed202;\n  z-index: 10;\n  border-radius: 0 2em 2em 0;\n  transition: .4s;\n}\n\n.switch input:checked + .slider {\n  background-color: #eed202;\n  z-index: 1;\n}\n\n.switch input:focus + .slider {\n  box-shadow: 0 0 4px #191A28;\n}\n\n.switch input:checked + .slider .circle {\n  transform: translateX(2em);\n}\n\n.switch input:checked + .slider .circle .divider {\n  left: 0;\n  width: 0.8em;\n  border-radius: 2em 0 0 2em;\n  background-color: #585F60;\n  z-index: 10;\n}",
