    css: "/* From Uiverse.io by nikk7007 - Tags: switch */\n.switch {\n --false: #E81B1B;\n --true: #009068;\n}\n\ninput[type=checkbox] {\n appearance: none;\n height: 2rem;\n width: 3.5rem;\n background-color: #fff;\n position: relative;\n border-radius: .2em;\n cursor: pointer;\n}\n\ninput[type=checkbox]::before {\n content: '';\n display: block;\n height: 1.9em;\n width: 1.9em;\n transform: translate(-50%, -50%);\n position: absolute;\n top: 50%;\n left: calc(1.9em/2 + .3em);\n background-color: var(--false);\n border-radius: .2em;\n transition: .3s ease;\n}\n\ninput[type=checkbox]:checked::before {\n background-color: var(--true);\n left: calc(100% - (1.9em/2 + .3em));\n}",
